    return;
}
var restMin = parseInt(flow.get('restMinutes') || '0');
if (isNaN(restMin) || restMin < 0) {
    node.send([null, {payload: '⚠️ Imposta un tempo di riposo valido (min)'}, null, null]);
    return;
}
var now = new Date();
var parts = target.split(':');
var th = parseInt(parts[0]), tm = parseInt(parts[1]);
var targetDate = new Date(now);
targetDate.setHours(th, tm, 0, 0);
if (targetDate <= now) targetDate.setDate(targetDate.getDate() + 1);

var PROG1_MS = 196 * 60 * 1000;
var PROG7_MS = 15 * 60 * 1000;
var STOP_OFFSET_MS = 3 * 60 * 1000;
var restMs = restMin * 60 * 1000;

// Validation: at least Prog 7 + Prog 1 must fit
if (targetDate - now < PROG1_MS + PROG7_MS) {
    node.send([null, {payload: '⚠️ Tempo insufficiente (servono ≥3h31m per Prog 7 + Prog 1)'}, null, null]);
    return;
}

var prog1StartMs = targetDate.getTime() - PROG1_MS;
var stopMs = targetDate.getTime() + STOP_OFFSET_MS;
var prog1At = new Date(prog1StartMs).toTimeString().slice(0, 5);
var stopAt = new Date(stopMs).toTimeString().slice(0, 5);
var cmd1 = 'start:1:1250g:dark:';
var cmd7 = 'start:7:::';
var usbEnabled = flow.get('usbCycleEnabled') || false;

// Ideal prog 7 start time
var idealProg7StartMs = prog1StartMs - restMs - PROG7_MS;
var prog7StartMs;
var restWarning = '';
var actualRestMin = restMin;

if (idealProg7StartMs < now.getTime()) {
    // Not enough time: start prog 7 immediately, prog 1 stays at target
    prog7StartMs = now.getTime();
    var actualRestMs = prog1StartMs - now.getTime() - PROG7_MS;
    actualRestMin = Math.max(0, Math.round(actualRestMs / 60000));
    restWarning = ' ⚠️ Tempo di riposo effettivo ' + actualRestMin + ' min invece di ' + restMin + ' min';
} else {
    prog7StartMs = idealProg7StartMs;
}
var prog7At = new Date(prog7StartMs).toTimeString().slice(0, 5);

flow.set('pendingCancelled', false);
var schedId = Date.now();
flow.set('pendingSchedId', schedId);
flow.set('pendingCmd', cmd1);
flow.set('pendingSendMs', prog1StartMs);
flow.set('pendingStopMs', stopMs);
flow.set('pendingProg7Ms', null);
flow.set('pendingProg7Cmd', null);

// Schedule prog 7 (immediate if in the past, delayed otherwise)
if (prog7StartMs <= now.getTime() + 1000) {
    node.send([{payload: cmd7}, {payload: '✅ Prog 7 avviato' + restWarning}, null, null]);
} else {
    flow.set('pendingProg7Ms', prog7StartMs);
    flow.set('pendingProg7Cmd', cmd7);
    var prog7Delay = prog7StartMs - now.getTime();
    setTimeout(function() {
        if (flow.get('pendingCancelled') || flow.get('pendingSchedId') !== schedId) return;
        flow.set('pendingProg7Ms', null);
        flow.set('pendingProg7Cmd', null);
        node.send([{payload: cmd7}, {payload: '✅ Inviato: ' + cmd7}, null, null]);
    }, prog7Delay);
    if (usbEnabled) {
        schedulePowerCycle(Math.max(0, prog7StartMs - 60000 - now.getTime()), schedId);
    }
}

// Schedule prog 1
scheduleCmd(cmd1, prog1StartMs, schedId, usbEnabled);

// Schedule stop
setTimeout(function() {
    if (flow.get('pendingCancelled') || flow.get('pendingSchedId') !== schedId) return;
    flow.set('pendingStopMs', null);
    node.send([{payload: 'stop'}, {payload: '⛔ Stop automatico inviato — buon appetito!'}, {payload: '{"events":[]}'}, null]);
}, stopMs - now.getTime());
if (usbEnabled) {
    schedulePowerCycle(Math.max(0, stopMs - 60000 - now.getTime()), schedId);
}

// Build events for file
var events = [];
if (prog7StartMs > now.getTime() + 1000) {
    events.push({cmd: cmd7, at: prog7StartMs});
}
events.push({cmd: cmd1, at: prog1StartMs});
events.push({cmd: 'stop', at: stopMs});

var fileMsg = {payload: JSON.stringify({events: events})};
var usbNote = usbEnabled ? ' — 🔌 Power cycle attivo' : '';
var statusMsg;
if (prog7StartMs <= now.getTime() + 1000) {
    statusMsg = '✅ Prog 7 ora' + restWarning + ' — ⏳ Prog 1 alle ' + prog1At + ' — Stop alle ' + stopAt + usbNote;
