var stopMs = flow.get('pendingStopMs');
var now = Date.now();
function fmt(ms) {
    var rem = Math.max(0, ms - now);
    var tot = Math.floor(rem / 1000);
    var h = Math.floor(tot / 3600);
    var m = Math.floor((tot % 3600) / 60);
    var s = tot % 60;
    return (h > 0 ? h + 'h ' : '') +
           (m > 0 || h > 0 ? String(m).padStart(2,'0') + 'm ' : '') +
           String(s).padStart(2,'0') + 's';
}
if (prog7Ms && prog7Ms > now) {
    var cmd7 = flow.get('pendingProg7Cmd') || '';
    return {payload: '⏳ Invio "' + cmd7 + '" tra ' + fmt(prog7Ms)};
}
if (sendMs && sendMs > now) {
    var cmd = flow.get('pendingCmd') || '';
    return {payload: '⏳ Invio "' + cmd + '" tra ' + fmt(sendMs)};
}
if (stopMs && stopMs > now) {
    return {payload: '⏳ Stop automatico tra ' + fmt(stopMs)};
}
return null;

var content = msg.payload || '{}';
var data;
try { data = JSON.parse(content); } catch(e) { return null; }
if (!data.events || !Array.isArray(data.events) || data.events.length === 0) return null;

var now = Date.now();
var FIVE_MIN = 5 * 60 * 1000;
var usbEnabled = flow.get('usbCycleEnabled') || false;

flow.set('pendingCancelled', false);
var schedId = Date.now();
flow.set('pendingSchedId', schedId);
flow.set('pendingProg7Ms', null);
flow.set('pendingProg7Cmd', null);

// Split events by kind and by time, keeping only future ones
var futureStarts = [];
var futureStop = null;
var recovered = [];
var lateWarnings = [];
var expired = [];

for (var i = 0; i < data.events.length; i++) {
    var ev = data.events[i];
    if (!ev.cmd || !ev.at) continue;
    var remaining = ev.at - now;
    if (remaining > 0) {
        (function(ev, remaining) {
            setTimeout(function() {
                if (flow.get('pendingCancelled') || flow.get('pendingSchedId') !== schedId) return;
                if (ev.cmd === 'stop') { flow.set('pendingStopMs', null); }
                else if (ev.cmd === flow.get('pendingProg7Cmd') && ev.at === flow.get('pendingProg7Ms')) {
                    flow.set('pendingProg7Ms', null); flow.set('pendingProg7Cmd', null);
                } else {
                    flow.set('pendingSendMs', null); flow.set('pendingCmd', null);
                }
                node.send([{payload: ev.cmd}, {payload: '✅ Inviato (da file): ' + ev.cmd}, null, null]);
            }, remaining);
        })(ev, remaining);
        if (usbEnabled) {
            (function(sendMs) {
                setTimeout(function() {
                    if (flow.get('pendingCancelled') || flow.get('pendingSchedId') !== schedId) return;
                    node.send([null, null, null, {payload: '{"state_1":"off"}'}]);
                    setTimeout(function() {
                        node.send([null, null, null, {payload: '{"state_1":"on"}'}]);
                    }, 5000);
                }, Math.max(0, sendMs - 60000 - now));
            })(ev.at);
        }
        if (ev.cmd === 'stop') { futureStop = ev.at; }
        else { futureStarts.push({cmd: ev.cmd, at: ev.at}); }
        recovered.push(ev.cmd + ' @ ' + new Date(ev.at).toTimeString().slice(0,5));
    } else if (remaining > -FIVE_MIN) {
        node.send([{payload: ev.cmd}, {payload: '✅ Inviato (in ritardo, da file): ' + ev.cmd}, null, null]);
        recovered.push(ev.cmd + ' (in ritardo)');
    } else {
        lateWarnings.push(ev.cmd + ' saltato (>' + Math.round(-remaining/60000) + ' min di ritardo)');
        expired.push(ev);
    }
}

// Sort future starts by time. Earliest = prog 7 (if there is more than one start), latest = prog 1.
futureStarts.sort(function(a, b) { return a.at - b.at; });
if (futureStarts.length >= 2) {
    flow.set('pendingProg7Cmd', futureStarts[0].cmd);
    flow.set('pendingProg7Ms', futureStarts[0].at);
    flow.set('pendingCmd', futureStarts[futureStarts.length - 1].cmd);
    flow.set('pendingSendMs', futureStarts[futureStarts.length - 1].at);
} else if (futureStarts.length === 1) {
    flow.set('pendingCmd', futureStarts[0].cmd);
    flow.set('pendingSendMs', futureStarts[0].at);
}
if (futureStop) { flow.set('pendingStopMs', futureStop); }

var statusParts = [];
if (recovered.length) statusParts.push('⏳ Ripristinati: ' + recovered.join(', '));
if (lateWarnings.length) statusParts.push('⚠️ ' + lateWarnings.join(' | '));
if (statusParts.length === 0) statusParts.push('ℹ️ File eventi vuoto o già scaduto');
node.send([null, {payload: statusParts.join(' — ')}, null, null]);

if (expired.length && (futureStarts.length || futureStop)) {
    var remaining_events = data.events.filter(function(ev) {
        return (ev.at - now) > -FIVE_MIN;
    });
    node.send([null, null, {payload: JSON.stringify({events: remaining_events})}, null]);
} else if (expired.length && !futureStarts.length && !futureStop) {
    node.send([null, null, {payload: '{"events":[]}'}, null]);
}
